import { 
  CalendarDays, 
  Star, 
  Clock, 
  User, 
  CheckCircle2, 
  Sparkles, 
  BarChart3, 
  FileText
} from "lucide-react";
import { getServerSession } from "next-auth";
import { authOptions } from "../../../../lib/auth";
import { prisma } from "../../../../lib/prisma";
import { format } from "date-fns";
import { redirect } from "next/navigation";

export default async function StudentDashboardPage() {
  const session = await getServerSession(authOptions);
  if (!session?.user?.id) {
    redirect("/login");
  }

  const studentId = session.user.id;

  // 1. Fetch the student's profile (for activeProgram info)
  const student = await prisma.user.findUnique({
    where: { id: studentId },
    select: { name: true, activeProgram: true },
  });

  // 2. Fetch Latest Evaluation (attendance with scores)
  const latestAttendance = await prisma.attendance.findFirst({
    where: { 
      studentId, 
      status: "PRESENT",
      OR: [
        { pronunciation: { not: null } },
        { fluency: { not: null } },
        { vocabulary: { not: null } },
        { tutorNotes: { not: null } }
      ]
    },
    orderBy: {
      session: {
        date: "desc"
      }
    },
    include: {
      session: {
        include: { tutor: { select: { name: true } } }
      }
    }
  });

  // 3. Fetch recent sessions (for upcoming schedule — sessions where this student has attendance)
  const upcomingAttendances = await prisma.attendance.findMany({
    where: {
      studentId,
      session: {
        date: { gte: new Date(new Date().setHours(0, 0, 0, 0)) },
        isCompleted: false,
      },
    },
    orderBy: { session: { date: "asc" } },
    take: 3,
    include: {
      session: {
        include: { tutor: { select: { name: true } } },
      },
    },
  });

  // 4. Attendance Summary
  const allAttendances = await prisma.attendance.findMany({
    where: { studentId },
  });

  const totalPresent = allAttendances.filter(a => a.status === "PRESENT").length;
  const absences = allAttendances.filter(a => ["ABSENT", "SICK", "EXCUSED"].includes(a.status)).length;
  const totalSessions = allAttendances.length;

  // Helper to render stars for evaluation metrics
  const renderStars = (score: number) => {
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <Star
            key={star}
            className={`w-4 h-4 transition-all ${
              star <= score ? "text-amber-400 fill-amber-400" : "text-slate-100 fill-slate-100"
            }`}
          />
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col gap-6 md:gap-8 max-w-5xl mx-auto px-4 md:px-6 lg:px-8 py-6 md:py-8 w-full">
      
      {/* 1. Welcome Header & Quick Status */}
      <div className="flex flex-col gap-3">
        <div>
          <h1 className="text-2xl md:text-3xl font-bold tracking-tight text-slate-900 flex items-center gap-2">
            Hello, {session.user.name?.split(" ")[0] || "Student"}! <Sparkles className="w-5 h-5 md:w-6 md:h-6 text-amber-500" />
          </h1>
          <p className="mt-1 text-sm font-medium text-slate-500">
            Ready to level up your English today?
          </p>
        </div>
        
        {student?.activeProgram ? (
          <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg w-fit shadow-sm bg-emerald-50 border border-emerald-100">
            <div className="w-2 h-2 rounded-full animate-pulse bg-emerald-500" />
            <span className="text-xs sm:text-sm font-bold tracking-wide text-emerald-800">
              Active: {student.activeProgram} Program
            </span>
          </div>
        ) : (
          <div className="inline-flex items-center gap-2 px-3 py-1.5 rounded-lg bg-slate-100 border border-slate-200 w-fit shadow-sm">
            <span className="text-xs sm:text-sm font-bold text-slate-600 tracking-wide">
              No Active Program Yet
            </span>
          </div>
        )}
      </div>

      {/* 2. Upcoming Schedule */}
      <div className="flex flex-col gap-4">
        <h2 className="text-lg md:text-xl font-bold tracking-tight text-slate-900 flex items-center gap-2">
          <CalendarDays className="w-5 h-5 text-blue-500" />
          Upcoming Schedule
        </h2>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {upcomingAttendances.length === 0 ? (
            <div className="sm:col-span-2 p-8 text-center bg-white border border-slate-200 rounded-2xl shadow-sm text-slate-500 font-medium">
              You do not have any upcoming sessions scheduled.
            </div>
          ) : (
            upcomingAttendances.map((att) => {
              const isToday = new Date(att.session.date).toDateString() === new Date().toDateString();
              const dateDisplay = isToday ? "Today" : format(new Date(att.session.date), "MMM dd, yyyy");

              return (
                <div 
                  key={att.id}
                  className="bg-white rounded-2xl border border-slate-200 p-5 shadow-sm transition-all duration-200 hover:shadow-md hover:border-blue-200 flex flex-col gap-4"
                >
                  <div className="flex items-start justify-between">
                    <div className="flex items-center gap-2">
                      <div className="p-2 rounded-lg bg-blue-50 text-blue-600">
                        <Clock className="w-5 h-5" />
                      </div>
                      <div>
                        <p className="text-xs font-bold text-slate-500 uppercase tracking-wider">{dateDisplay}</p>
                        <p className="text-sm font-bold text-slate-900">{att.session.timeSlot}</p>
                      </div>
                    </div>
                  </div>
                  
                  <div>
                    <h3 className="text-base font-bold mb-1 text-slate-900">
                      {att.session.title}
                    </h3>
                    <div className="flex items-center gap-2 text-sm font-medium text-slate-500 mb-1">
                      <User className="w-4 h-4 text-slate-400" />
                      {att.session.tutor.name}
                    </div>
                    <span className="inline-flex items-center rounded-md px-2 py-0.5 text-[10px] font-bold tracking-wider bg-blue-50 text-blue-600 border border-blue-100 uppercase">
                      {att.session.programType}
                    </span>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 lg:gap-8 items-start">
        
        {/* 3. Performance & Evaluation Metrics */}
        <div className="lg:col-span-2 flex flex-col gap-4">
          <h2 className="text-lg md:text-xl font-bold tracking-tight text-slate-900 flex items-center gap-2">
            <BarChart3 className="w-5 h-5 text-indigo-500" />
            Latest Evaluation
          </h2>
          
          {!latestAttendance ? (
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-8 text-center text-slate-500 font-medium h-full flex items-center justify-center">
              You haven&apos;t received any evaluations yet. Keep up the good work and check back later!
            </div>
          ) : (
            <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden flex flex-col transition-all duration-200 hover:shadow-md">
              {/* Eval Header */}
              <div className="bg-indigo-50/50 p-5 sm:px-6 border-b border-slate-100 flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                <div>
                  <h3 className="text-base font-bold text-slate-900">{latestAttendance.session.title} • {latestAttendance.session.timeSlot}</h3>
                  <p className="text-sm font-medium text-slate-500 flex items-center gap-2 mt-1">
                    <CalendarDays className="w-4 h-4" /> {format(new Date(latestAttendance.session.date), "MMM dd, yyyy")}
                  </p>
                </div>
                <div className="inline-flex items-center gap-2 bg-white border border-slate-200 px-3 py-1.5 rounded-lg text-sm font-semibold text-slate-700 shadow-sm">
                  <User className="w-4 h-4 text-slate-400" />
                  By {latestAttendance.session.tutor.name}
                </div>
              </div>
              
              {/* Eval Body */}
              <div className="p-5 sm:p-6 flex flex-col gap-6">
                {/* Metrics Grid */}
                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                  {[
                    { key: "Pronunciation", score: latestAttendance.pronunciation },
                    { key: "Fluency", score: latestAttendance.fluency },
                    { key: "Vocabulary", score: latestAttendance.vocabulary },
                  ].map(({key, score}) => (
                    score ? (
                      <div key={key} className="flex flex-col gap-2 p-4 rounded-xl bg-slate-50 border border-slate-100">
                        <span className="text-[10px] md:text-xs font-bold text-slate-500 uppercase tracking-widest">{key}</span>
                        <div className="flex items-center justify-between">
                          <span className="text-lg md:text-xl font-bold text-slate-900">{score}<span className="text-xs md:text-sm text-slate-400">/5</span></span>
                          {renderStars(score ?? 0)}
                        </div>
                      </div>
                    ) : null
                  ))}
                </div>
                
                {/* Tutor Notes */}
                {latestAttendance.tutorNotes && (
                  <div className="rounded-xl bg-blue-50/50 border border-blue-100 p-4 sm:p-5">
                    <div className="flex items-center gap-2 mb-2">
                      <FileText className="w-4 h-4 text-blue-600" />
                      <span className="text-sm font-bold text-blue-900">Tutor Feedback</span>
                    </div>
                    <p className="text-sm leading-relaxed text-blue-800/80 font-medium italic">
                      &quot;{latestAttendance.tutorNotes}&quot;
                    </p>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>

        {/* 4. Attendance Summary Card */}
        <div className="lg:col-span-1 flex flex-col gap-4">
          <h2 className="text-lg md:text-xl font-bold tracking-tight text-slate-900 flex items-center gap-2">
             <CheckCircle2 className="w-5 h-5 text-teal-500" />
            Attendance
          </h2>
          
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6 flex flex-col gap-5 transition-all duration-200 hover:shadow-md">
            
            <div className="flex items-center justify-between border-b border-slate-100 pb-4">
              <span className="text-sm font-medium text-slate-600">Total Present</span>
              <span className="text-2xl font-bold text-teal-600">{totalPresent}</span>
            </div>
            
            <div className="flex items-center justify-between border-b border-slate-100 pb-4">
              <span className="text-sm font-medium text-slate-600">Absences</span>
              <span className="text-lg font-bold text-amber-600">{absences}</span>
            </div>
            
            <div className="flex items-center justify-between pt-1">
              <span className="text-sm font-medium text-slate-600">Total Sessions</span>
              <span className="text-lg font-bold text-slate-900">{totalSessions}</span>
            </div>
            
            {/* Visual Progress Bar */}
            {totalSessions > 0 && (
              <div className="mt-2 text-center">
                <div className="w-full h-2 bg-slate-100 rounded-full overflow-hidden mb-2">
                  <div 
                    className="h-full bg-teal-500 rounded-full transition-all duration-1000 ease-out" 
                    style={{ width: `${totalSessions > 0 ? (totalPresent / totalSessions) * 100 : 0}%` }}
                  />
                </div>
                <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">Attendance Rate</span>
              </div>
            )}
          </div>
        </div>

      </div>
    </div>
  );
}
